    ).data;
    const pasta = schedule.groceryItems.filter((row: any) => row.normalizedKey === 'pasta');
    expect(pasta).toHaveLength(1);
    expect(pasta[0].quantity).toEqual({ kind: 'scalar', value: { n: '500', d: '1' } });
