 const stamp=String(Date.now());const token=stamp+'.'+crypto.createHmac('sha256',secret).update(stamp).digest('base64url');
 await context.addCookies([{name:'h_access',value:token,url:base},{name:'x-family-member-id',value:member,url:base}]);
 await context.addInitScript(({family,member})=>{localStorage.setItem('locale','en');localStorage.setItem('family-storage',JSON.stringify({state:{selectedFamilyMemberId:member,familyMembers:family,_hasHydrated:true,hasLoaded:true},version:0}));},{family,member});
